CREATE TABLE IF NOT EXISTS "User" ("id" TEXT NOT NULL PRIMARY KEY, "email" TEXT NOT NULL, "name" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "User_email_key" ON "User"("email");
CREATE TABLE IF NOT EXISTS "Post" ("id" TEXT NOT NULL PRIMARY KEY, "title" TEXT NOT NULL, "content" TEXT, "published" BOOLEAN NOT NULL DEFAULT false, "authorId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS "LocalOrder" ("id" TEXT NOT NULL PRIMARY KEY, "displayId" TEXT NOT NULL, "requestId" TEXT, "createdAt" BIGINT NOT NULL, "isArchived" BOOLEAN NOT NULL DEFAULT false, "stockApplied" BOOLEAN NOT NULL DEFAULT false, "data" TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "LocalOrder_displayId_key" ON "LocalOrder"("displayId");
CREATE UNIQUE INDEX IF NOT EXISTS "LocalOrder_requestId_key" ON "LocalOrder"("requestId");
CREATE INDEX IF NOT EXISTS "LocalOrder_createdAt_idx" ON "LocalOrder"("createdAt");
CREATE TABLE IF NOT EXISTS "LocalOrderItem" ("id" TEXT NOT NULL PRIMARY KEY, "orderId" TEXT NOT NULL, "data" TEXT NOT NULL, CONSTRAINT "LocalOrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "LocalOrder" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "LocalOrderItem_orderId_idx" ON "LocalOrderItem"("orderId");
CREATE TABLE IF NOT EXISTS "LocalCounter" ("name" TEXT NOT NULL PRIMARY KEY, "value" INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS "LocalInventory" ("id" TEXT NOT NULL PRIMARY KEY, "quantity" REAL NOT NULL, "data" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "LocalSerial" ("serialNumber" TEXT NOT NULL PRIMARY KEY, "productId" TEXT NOT NULL, "status" TEXT NOT NULL, "addedAt" BIGINT NOT NULL, "soldAt" BIGINT, "orderId" TEXT, "data" TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS "LocalSerial_productId_status_idx" ON "LocalSerial"("productId", "status");
CREATE TABLE IF NOT EXISTS "LocalMenu" ("id" TEXT NOT NULL, "kind" TEXT NOT NULL, "position" INTEGER NOT NULL DEFAULT 0, "data" TEXT NOT NULL, PRIMARY KEY ("kind", "id"));
CREATE INDEX IF NOT EXISTS "LocalMenu_kind_position_idx" ON "LocalMenu"("kind", "position");
CREATE TABLE IF NOT EXISTS "LocalCoupon" ("id" TEXT NOT NULL PRIMARY KEY, "code" TEXT NOT NULL, "usageCount" INTEGER NOT NULL DEFAULT 0, "data" TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "LocalCoupon_code_key" ON "LocalCoupon"("code");
CREATE TABLE IF NOT EXISTS "LocalCouponUsage" ("id" TEXT NOT NULL PRIMARY KEY, "couponId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "timestamp" BIGINT NOT NULL, "data" TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS "LocalCouponUsage_couponId_timestamp_idx" ON "LocalCouponUsage"("couponId", "timestamp");
CREATE TABLE IF NOT EXISTS "LocalMetadata" ("key" TEXT NOT NULL PRIMARY KEY, "value" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "LocalNotice" ("id" TEXT NOT NULL PRIMARY KEY, "data" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "_LocalMigrations" ("name" TEXT NOT NULL PRIMARY KEY, "checksum" TEXT NOT NULL, "appliedAt" INTEGER NOT NULL);
